CREATE TABLE "article__en_new" (
            id TEXT PRIMARY KEY,
            kind TEXT NOT NULL,
            title TEXT,
            source TEXT,
            source_hash TEXT,
            date TEXT,
            metadata TEXT,       -- JSON, verbatim source metadata
            open_questions TEXT,   -- JSON array
            evidenced INTEGER,
            generated_at TEXT
        , thin INTEGER DEFAULT 0, last_processed TEXT, time_source TEXT, host TEXT, last_from TEXT, from_source TEXT, logical_id TEXT, id_source TEXT, epistemic_class TEXT, status TEXT, scope TEXT, tags TEXT, confidence REAL, project TEXT, project_kind TEXT, sphere TEXT, origin TEXT DEFAULT 'measured' CHECK (origin IN ('measured','user')), expire INTEGER DEFAULT 0, protected INTEGER DEFAULT 0);
INSERT INTO "article__en_new" ("id", "kind", "title", "source", "source_hash", "date", "metadata", "open_questions", "evidenced", "generated_at", "thin", "last_processed", "time_source", "host", "last_from", "from_source", "logical_id", "id_source", "epistemic_class", "status", "scope", "tags", "confidence", "project", "project_kind", "sphere", "origin", "expire", "protected") SELECT "id", "kind", "title", "source", "source_hash", "date", "metadata", "open_questions", "evidenced", CASE "generated_at" WHEN 'gemessen' THEN 'measured' ELSE "generated_at" END, "thin", "last_processed", "time_source", "host", "last_from", "from_source", "logical_id", "id_source", "epistemic_class", "status", "scope", "tags", "confidence", "project", "project_kind", "sphere", CASE "origin" WHEN 'gemessen' THEN 'measured' WHEN 'nutzer' THEN 'user' ELSE "origin" END, "expire", "protected" FROM "article";
DROP TABLE "article";
ALTER TABLE "article__en_new" RENAME TO "article";
