INSERT INTO "eos_bug_hypotheses__en_new" ("bug_id", "user_id", "ts", "description", "wo", "status", "finding") SELECT CASE "bug_id" WHEN 'OFFEN' THEN 'OPEN' ELSE "bug_id" END, "user_id", "ts", "description", "wo", CASE "status" WHEN 'OFFEN' THEN 'OPEN' WHEN 'REPRODUZIERT' THEN 'REPRODUCED' WHEN 'WIDERLEGT' THEN 'REFUTED' WHEN 'BEHOBEN' THEN 'FIXED' ELSE "status" END, "finding" FROM "eos_bug_hypotheses";
