CREATE TABLE "error__en_new" (
            id TEXT PRIMARY KEY,
            kind TEXT NOT NULL CHECK (kind IN ('sql', 'shell', 'python', 'data', 'provenance', 'method')),
            trigger_pattern TEXT NOT NULL,
            was_happened TEXT NOT NULL,
            how_recognized TEXT NOT NULL,
            how_avoided TEXT NOT NULL,
            severity TEXT NOT NULL CHECK (severity IN ('high', 'medium', 'low')),
            evidence TEXT NOT NULL,
            source TEXT NOT NULL,
            recognized_at TEXT,
            confirmed_through TEXT
        );
INSERT INTO "error__en_new" ("id", "kind", "trigger_pattern", "was_happened", "how_recognized", "how_avoided", "severity", "evidence", "source", "recognized_at", "confirmed_through") SELECT "id", CASE "kind" WHEN 'daten' THEN 'data' WHEN 'provenienz' THEN 'provenance' WHEN 'methode' THEN 'method' ELSE "kind" END, "trigger_pattern", "was_happened", "how_recognized", "how_avoided", CASE "severity" WHEN 'hoch' THEN 'high' WHEN 'mittel' THEN 'medium' WHEN 'niedrig' THEN 'low' ELSE "severity" END, "evidence", "source", "recognized_at", "confirmed_through" FROM "error";
