CREATE TABLE "conclusion__en_new" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kind TEXT NOT NULL CHECK (kind IN ('hypothesis','implication','lesson')),
            statement TEXT NOT NULL,
            reasoning TEXT,
            applies_for TEXT NOT NULL,
            author TEXT,
            time TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','supported','refuted','resolved')),
            refuted_through INTEGER REFERENCES conclusion(id)
        , confidence REAL);
INSERT INTO "conclusion__en_new" ("id", "kind", "statement", "reasoning", "applies_for", "author", "time", "status", "refuted_through", "confidence") SELECT "id", CASE "kind" WHEN 'hypothese' THEN 'hypothesis' WHEN 'implikation' THEN 'implication' WHEN 'lehre' THEN 'lesson' ELSE "kind" END, "statement", "reasoning", "applies_for", "author", "time", CASE "status" WHEN 'offen' THEN 'open' WHEN 'gestuetzt' THEN 'supported' WHEN 'widerlegt' THEN 'refuted' WHEN 'abgeloest' THEN 'resolved' ELSE "status" END, "refuted_through", "confidence" FROM "conclusion";
