            conclusion_id INTEGER NOT NULL REFERENCES conclusion(id),
            evidence_kind TEXT NOT NULL CHECK (evidence_kind IN
                ('protocol','article','measurement','problem','edge','file')),
            evidence_id TEXT NOT NULL,
            PRIMARY KEY (conclusion_id, evidence_kind, evidence_id)
        );
INSERT INTO "conclusion_evidence__en_new" ("conclusion_id", "evidence_kind", "evidence_id") SELECT "conclusion_id", CASE "evidence_kind" WHEN 'protokoll' THEN 'protocol' WHEN 'artikel' THEN 'article' WHEN 'messung' THEN 'measurement' WHEN 'kante' THEN 'edge' WHEN 'datei' THEN 'file' ELSE "evidence_kind" END, "evidence_id" FROM "conclusion_evidence";
