CREATE TABLE "kb_task__en_new" (
            id               INTEGER PRIMARY KEY AUTOINCREMENT,
            process           TEXT NOT NULL,
            payload          TEXT NOT NULL,
            state           TEXT NOT NULL DEFAULT 'open'
                              CHECK (state IN ('open','running','finished','unusable')),
            attempts          INTEGER NOT NULL DEFAULT 0,
            last_reason     TEXT,
            blocked_lanes  TEXT,
            created          TEXT NOT NULL,
            changed         TEXT NOT NULL,
            -- inoperable WITHOUT reason is forbidden: otherwise no one knows anymore,
            -- why something was left lying, and the order is effectively lost.
            CHECK (state <> 'unusable'
                   OR (last_reason IS NOT NULL AND TRIM(last_reason) <> ''))
        );
INSERT INTO "kb_task__en_new" ("id", "process", "payload", "state", "attempts", "last_reason", "blocked_lanes", "created", "changed") SELECT "id", "process", "payload", CASE "state" WHEN 'offen' THEN 'open' WHEN 'laeuft' THEN 'running' WHEN 'fertig' THEN 'finished' WHEN 'unbedienbar' THEN 'unusable' ELSE "state" END, "attempts", "last_reason", "blocked_lanes", "created", CASE "changed" WHEN 'unbedienbar' THEN 'unusable' ELSE "changed" END FROM "kb_task";
DROP TABLE "kb_task";
ALTER TABLE "kb_task__en_new" RENAME TO "kb_task";
