INSERT INTO "kb_booking__en_new" ("id", "time", "account", "access", "amount", "unit", "purpose", "batch_id", "activity_id", "key_hint", "source", "raw_hash") SELECT "id", "time", "account", "access", "amount", "unit", "purpose", "batch_id", "activity_id", "key_hint", CASE "source" WHEN 'buchen' THEN 'book' ELSE "source" END, "raw_hash" FROM "kb_booking";
