            access                    TEXT PRIMARY KEY,
            display                    TEXT NOT NULL,
            unit                    TEXT,
            window_duration_seconds      INTEGER,
            window_limit                REAL,
            week_limit                  REAL,
            tag_limit                    REAL,
            minute_limit                 REAL,
            day_switch_hour          INTEGER,
