CREATE TABLE "view_evidence__en_new" (
  evidence_id        TEXT PRIMARY KEY,
  capture_id       TEXT NOT NULL,
  source_id         TEXT NOT NULL,
  source_epoch     INTEGER NOT NULL,
  capture_time     REAL,
  entrance_time      REAL NOT NULL,
  -- Not the pixels, only their fingerprint. The image stays in the
  -- file storage; a database is the wrong place for image data, and a
  -- hash suffices to later prove it was the same image.
  raw_reference_hash     TEXT,
  room_reference        TEXT,
  transformation    TEXT NOT NULL,
  transformation_version TEXT NOT NULL,
  observation_type   TEXT NOT NULL,
  value              TEXT NOT NULL,
  bottom_up_precision REAL,
  -- ⚠️ NR-RET-012: YOLO confidence, CLIP cosine and OCR quality are NOT
  -- comparable. This column tells against which calibration the number
  -- may be read. If 'UNCALIBRATED' is here, the number is only
  -- ordering within the same transformation, not across transformations.
  calibration_ref  TEXT NOT NULL DEFAULT 'UNCALIBRATED',
  -- Constant. A column that always says the same thing is intentional here: it
  -- appears in every line that someone reads.
  authority        TEXT NOT NULL DEFAULT 'ONLY_OBSERVATION',
  generated_at        REAL NOT NULL
);
INSERT INTO "view_evidence__en_new" ("evidence_id", "capture_id", "source_id", "source_epoch", "capture_time", "entrance_time", "raw_reference_hash", "room_reference", "transformation", "transformation_version", "observation_type", "value", "bottom_up_precision", "calibration_ref", "authority", "generated_at") SELECT "evidence_id", "capture_id", "source_id", "source_epoch", "capture_time", "entrance_time", "raw_reference_hash", "room_reference", "transformation", "transformation_version", "observation_type", "value", "bottom_up_precision", CASE "calibration_ref" WHEN 'UNKALIBRIERT' THEN 'UNCALIBRATED' ELSE "calibration_ref" END, CASE "authority" WHEN 'NUR_BEOBACHTUNG' THEN 'ONLY_OBSERVATION' ELSE "authority" END, "generated_at" FROM "view_evidence";
